    }
  };
  filter.addEventListener('change', renderTasks);
  priorityFilter.addEventListener('change', renderTasks);
  renderTasks();
}

async function renderProjectWithAlert(id, message, filter = 'all', priority = 'all') {
  await renderProject(id, filter, priority);
  const alert = document.createElement('p');
  alert.className = 'alert';
  alert.setAttribute('role', 'alert');
  alert.textContent = message;
  app.insertBefore(alert, app.querySelector('.task-form'));
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  try {
    if (match) await renderProject(match[1]);
    else await renderList();
  } catch {
    await renderList('Unable to load projects');
  }
}

